const fs = require('fs');

function main() {
  const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
  const n = input[0];
  const grid = [];
  let idx = 1;
  let zeroRow = -1;
  let zeroCol = -1;

  for (let i = 0; i < n; i++) {
    grid.push([]);
    for (let j = 0; j < n; j++) {
      const value = input[idx++];
      grid[i].push(value);
      if (value === 0) {
        zeroRow = i;
        zeroCol = j;
      }
    }
  }

  let magicSum = null;

  for (let i = 0; i < n; i++) {
    if (i !== zeroRow) {
      let sum = 0;
      for (let j = 0; j < n; j++) {
        sum += grid[i][j];
      }
      magicSum = sum;
      break;
    }
  }

  let zeroRowSum = 0;
  for (let j = 0; j < n; j++) {
    zeroRowSum += grid[zeroRow][j];
  }

  const missingValue = magicSum - zeroRowSum;

  console.log(missingValue);
  console.log(zeroRow + 1);
  console.log(zeroCol + 1);
}

main();
